CREATE TABLE customer_survey_form_templates (
 key text NOT NULL,
 version integer NOT NULL CHECK(version>0),
 customer_code text NOT NULL,
 payload jsonb NOT NULL,
 source_reference text NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(key,version)
);
CREATE TRIGGER immutable_customer_survey_template BEFORE UPDATE OR DELETE ON customer_survey_form_templates FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
